@import '@fontsource/cinzel/400.css';
@import '@fontsource/cinzel/600.css';
@import '@fontsource/cinzel/700.css';
@import '@fontsource/cinzel/800.css';
@import '@fontsource/barlow-condensed/400.css';
@import '@fontsource/barlow-condensed/500.css';
@import '@fontsource/barlow-condensed/600.css';
@import '@fontsource/barlow-condensed/700.css';

:root {
  --ink: #090806;
  --bone: #f2e8cf;
  --sand: #d5b778;
  --gold: #e6b94e;
  --gold-bright: #ffd875;
  --gold-dark: #8b5e19;
  --rust: #9c3e22;
  --blood: #b83425;
  --moss: #586b42;
  --glass: rgba(12, 11, 8, 0.68);
  --line: rgba(230, 185, 78, 0.38);
  --serif: 'Cinzel', 'Palatino Linotype', Georgia, serif;
  --sans: 'Barlow Condensed', 'Arial Narrow', sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: var(--ink); }
body {
  color: var(--bone);
  font-family: var(--sans);
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
.hidden { display: none !important; }
kbd {
  display: inline-grid; place-items: center;
  min-width: 20px; height: 19px; padding: 0 5px;
  border: 1px solid rgba(230, 185, 78, 0.45);
  border-radius: 3px;
  background: rgba(255, 238, 190, 0.08);
  color: #f4dfa8;
  font-family: var(--sans);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.35);
}

#app { position: fixed; inset: 0; overflow: hidden; background: #0b0a07; }
#game { display: block; width: 100%; height: 100%; touch-action: none; }

#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 3;
  background:
    radial-gradient(ellipse at center, transparent 43%, rgba(6, 5, 3, 0.35) 76%, rgba(5, 4, 3, 0.86) 100%),
    linear-gradient(180deg, rgba(5, 4, 3, 0.2), transparent 22%, transparent 74%, rgba(5, 4, 3, 0.35));
  mix-blend-mode: multiply;
}
#grain {
  position: absolute; inset: -40%; pointer-events: none; z-index: 4; opacity: 0.13;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.85'/%3E%3C/svg%3E");
  animation: grain 0.24s steps(2) infinite;
  mix-blend-mode: overlay;
}
@keyframes grain {
  0% { transform: translate(0, 0); } 25% { transform: translate(2%, -1%); }
  50% { transform: translate(-1%, 2%); } 75% { transform: translate(1%, 1%); } 100% { transform: translate(-2%, -1%); }
}
#damage-flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 13; opacity: 0;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(154, 22, 12, 0.64) 100%);
  transition: opacity 0.18s ease;
}
#damage-flash.active { opacity: 1; transition: none; }
#fade {
  position: absolute; inset: 0; pointer-events: none; z-index: 40; opacity: 0;
  background: #070604; transition: opacity 0.45s ease;
}
#fade.active { opacity: 1; }
#cinematic-bars { position: absolute; inset: 0; pointer-events: none; z-index: 5; }
#cinematic-bars span { position: absolute; left: 0; right: 0; height: 0; background: #070604; transition: height 0.7s cubic-bezier(.2,.7,.2,1); }
#cinematic-bars span:first-child { top: 0; }
#cinematic-bars span:last-child { bottom: 0; }
.cinematic #cinematic-bars span { height: 7vh; }

/* ============================= HUD ============================= */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; padding: calc(18px + var(--safe-top)) calc(24px + var(--safe-right)) calc(18px + var(--safe-bottom)) calc(24px + var(--safe-left)); }
.hud-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; }
.eyebrow { font-family: var(--sans); font-size: 9px; font-weight: 600; letter-spacing: 0.24em; text-transform: uppercase; color: rgba(242, 232, 207, 0.58); }
.level-plate {
  min-width: 112px; padding: 9px 13px 8px;
  background: linear-gradient(105deg, rgba(9, 8, 6, 0.78), rgba(9, 8, 6, 0.38));
  border-left: 2px solid var(--gold);
  backdrop-filter: blur(8px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
}
.level-plate strong { display: inline-block; margin: 0 7px 0 0; font: 700 27px/1 var(--serif); color: var(--gold-bright); letter-spacing: 0.04em; text-shadow: 0 2px 10px #000; }
.level-plate > span:last-child { font-size: 11px; letter-spacing: 0.15em; color: var(--bone); opacity: 0.8; }
.hearts-block { display: flex; align-items: center; gap: 14px; padding-top: 5px; }
.hearts { display: flex; gap: 5px; filter: drop-shadow(0 3px 5px rgba(0,0,0,0.6)); }
.heart { width: 26px; height: 25px; position: relative; transition: transform 0.25s ease; }
.heart svg { width: 100%; height: 100%; overflow: visible; }
.heart path { fill: #d74532; stroke: #f19a67; stroke-width: 0.75; filter: drop-shadow(0 0 5px rgba(219, 63, 40, 0.5)); }
.heart.empty path { fill: rgba(24, 19, 13, 0.72); stroke: rgba(222, 198, 146, 0.32); filter: none; }
.heart.lost { animation: heartLost 0.55s ease; }
.heart.gain { animation: heartGain 0.5s ease; }
@keyframes heartLost { 0% { transform: scale(1.5) rotate(-7deg); filter: brightness(2); } 100% { transform: scale(1); } }
@keyframes heartGain { 0% { transform: scale(0); } 65% { transform: scale(1.3); } 100% { transform: scale(1); } }
.score { font: 600 13px/1 var(--sans); letter-spacing: 0.14em; color: var(--sand); }
.objective-card {
  max-width: 340px; flex: 1; text-align: center; padding: 7px 16px 6px;
  background: radial-gradient(ellipse at top, rgba(13, 11, 8, 0.76), rgba(13, 11, 8, 0.18));
  border-top: 1px solid rgba(230, 185, 78, 0.18);
  text-shadow: 0 2px 8px #000;
}
#hud-objective { margin-top: 2px; font: 600 17px/1.15 var(--serif); color: #f2e7c9; letter-spacing: 0.045em; }
.objective-route { display: flex; align-items: center; justify-content: center; gap: 7px; margin-top: 3px; font: 500 10px/1 var(--sans); letter-spacing: 0.16em; color: var(--sand); }
.objective-route i { display: block; width: 22px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.resources { display: flex; align-items: center; gap: 8px; }
.resource {
  display: flex; align-items: center; gap: 7px; min-width: 60px; padding: 7px 9px;
  background: var(--glass); border: 1px solid rgba(230, 185, 78, 0.2);
  backdrop-filter: blur(7px);
}
.resource svg { width: 20px; height: 20px; fill: var(--gold); filter: drop-shadow(0 0 4px rgba(230,185,78,.35)); }
.resource svg .cut { fill: #181209; }
.resource span { font: 600 14px/1 var(--sans); letter-spacing: 0.08em; color: #f1dfb4; }

.compass-wrap {
  position: absolute; top: calc(98px + var(--safe-top)); right: calc(26px + var(--safe-right));
  display: flex; flex-direction: column; align-items: center; gap: 5px; opacity: 0.92;
}
.compass-ring {
  position: relative; width: 66px; height: 66px; border-radius: 50%;
  border: 1px solid rgba(230, 185, 78, 0.42);
  background: radial-gradient(circle, rgba(14, 12, 8, 0.66), rgba(14, 12, 8, 0.2) 64%, transparent 66%);
  box-shadow: inset 0 0 18px rgba(0,0,0,.6), 0 0 0 4px rgba(9,8,6,.18);
}
.compass-ring::after { content: ''; position: absolute; inset: 8px; border: 1px dashed rgba(230, 185, 78, 0.16); border-radius: 50%; }
.compass-ring span { position: absolute; font: 500 7px/1 var(--sans); color: rgba(242,232,207,.5); }
.compass-ring .north { top: 4px; left: 50%; transform: translateX(-50%); color: var(--gold); }
.compass-ring .east { right: 5px; top: 50%; transform: translateY(-50%); }
.compass-ring .south { bottom: 4px; left: 50%; transform: translateX(-50%); }
.compass-ring .west { left: 5px; top: 50%; transform: translateY(-50%); }
.compass-arrow {
  position: absolute; left: calc(50% - 1px); top: 10px; width: 2px; height: 22px;
  background: linear-gradient(180deg, var(--gold-bright), rgba(230,185,78,.1));
  transform-origin: 50% 23px;
  box-shadow: 0 0 7px rgba(255, 216, 117, 0.7);
}
.compass-arrow::before { content: ''; position: absolute; top: -3px; left: -4px; border-left: 5px solid transparent; border-right: 5px solid transparent; border-bottom: 8px solid var(--gold-bright); }
.compass-center { position: absolute; left: calc(50% - 3px); top: calc(50% - 3px); width: 6px; height: 6px; border-radius: 50%; background: var(--bone); box-shadow: 0 0 8px var(--gold); }
.compass-caption { display: flex; gap: 7px; font: 500 8px/1 var(--sans); letter-spacing: .16em; color: rgba(242,232,207,.62); }
.compass-caption b { color: var(--sand); font-weight: 600; }

.route-strip {
  position: absolute; left: 50%; bottom: calc(82px + var(--safe-bottom)); width: min(420px, 42vw); height: 15px; transform: translateX(-50%); opacity: .8;
}
.route-line { position: absolute; left: 0; right: 0; top: 7px; height: 1px; background: linear-gradient(90deg, rgba(230,185,78,.06), rgba(230,185,78,.34) 50%, rgba(230,185,78,.06)); }
.route-player { position: absolute; top: 2px; width: 11px; height: 11px; transform: translateX(-50%) rotate(45deg); background: var(--bone); box-shadow: 0 0 10px rgba(242,232,207,.8); transition: left .1s linear; }
.route-relic { position: absolute; right: 0; top: 1px; width: 13px; height: 13px; transform: rotate(45deg); border: 1px solid var(--gold); background: rgba(230,185,78,.18); box-shadow: 0 0 8px rgba(230,185,78,.4); }
.route-secrets { position: absolute; inset: 0; }
.route-secrets i { position: absolute; top: 4px; width: 7px; height: 7px; border-radius: 50%; border: 1px solid rgba(230,185,78,.6); transform: translateX(-50%); }
.route-secrets i.found { background: var(--gold); box-shadow: 0 0 7px rgba(230,185,78,.8); }

.boss-bar { position: absolute; top: calc(88px + var(--safe-top)); left: 50%; transform: translateX(-50%); width: min(520px, 56vw); }
.boss-heading { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 5px; color: var(--bone); font: 600 10px/1 var(--sans); letter-spacing: .2em; }
.boss-heading b { color: var(--gold); font-weight: 600; }
.boss-track { height: 7px; padding: 1px; background: rgba(8,7,5,.8); border: 1px solid rgba(230,185,78,.45); box-shadow: 0 2px 12px #000; }
.boss-track i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #7f1f14, #c6552d 60%, #e7ad4d); box-shadow: 0 0 10px rgba(198,85,45,.6); transition: width .2s ease; }

.interact-prompt {
  position: absolute; left: 50%; bottom: calc(112px + var(--safe-bottom)); transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px; padding: 8px 14px;
  background: rgba(9, 8, 6, 0.8); border: 1px solid rgba(230,185,78,.32);
  font: 600 10px/1 var(--sans); letter-spacing: .16em; color: var(--bone);
  box-shadow: 0 6px 30px rgba(0,0,0,.5); backdrop-filter: blur(8px);
}
.interact-prompt kbd { border-color: var(--gold); color: var(--gold-bright); }
.toast-stack { position: absolute; left: 50%; top: 25%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 6px; width: min(500px, 80vw); }
.toast {
  padding: 8px 18px; background: linear-gradient(90deg, transparent, rgba(9,8,6,.88) 16%, rgba(9,8,6,.88) 84%, transparent);
  text-align: center; font: 600 12px/1.2 var(--sans); letter-spacing: .16em; color: #f0dfba;
  animation: toastIn 2.8s ease both; text-shadow: 0 2px 6px #000;
}
.toast b { color: var(--gold-bright); }
.toast.gold { color: var(--gold-bright); }
@keyframes toastIn { 0% { opacity: 0; transform: translateY(7px); } 12%, 78% { opacity: 1; transform: none; } 100% { opacity: 0; transform: translateY(-4px); } }
.hint-card {
  position: absolute; left: 50%; bottom: calc(180px + var(--safe-bottom)); transform: translateX(-50%);
  width: min(430px, 82vw); padding: 12px 18px; text-align: center;
  background: rgba(10, 9, 6, 0.78); border-top: 1px solid rgba(230,185,78,.32); border-bottom: 1px solid rgba(230,185,78,.12);
  backdrop-filter: blur(8px); font: 500 12px/1.4 var(--sans); letter-spacing: .08em; color: #eadbb9;
  animation: hintIn .35s ease both;
}
.hint-card b { color: var(--gold-bright); font-weight: 600; }
.hint-card .hint-key { color: var(--gold-bright); border: 1px solid rgba(230,185,78,.4); padding: 1px 5px; margin: 0 3px; font-size: 10px; }
@keyframes hintIn { from { opacity: 0; transform: translate(-50%, 6px); } }

.desktop-hints {
  position: absolute; left: 50%; bottom: calc(18px + var(--safe-bottom)); transform: translateX(-50%);
  display: flex; gap: 16px; padding: 6px 14px; white-space: nowrap;
  font: 500 8px/1 var(--sans); letter-spacing: .13em; color: rgba(242,232,207,.42);
  background: rgba(9,8,6,.34); border-radius: 2px;
}
.desktop-hints span { display: flex; align-items: center; gap: 5px; }
.desktop-hints kbd { height: 16px; min-width: 17px; font-size: 8px; border-color: rgba(230,185,78,.25); color: rgba(242,232,207,.68); }
.pause-button {
  position: absolute; top: calc(22px + var(--safe-top)); left: 50%; transform: translateX(-50%);
  width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; gap: 4px;
  border: 1px solid rgba(230,185,78,.26); border-radius: 50%; background: rgba(9,8,6,.43); pointer-events: auto;
  opacity: .7; transition: opacity .2s, background .2s;
}
.pause-button:hover { opacity: 1; background: rgba(9,8,6,.76); }
.pause-button span { width: 2px; height: 9px; background: var(--bone); }

/* ============================= TOUCH ============================= */
.touch-ui { position: absolute; inset: 0; z-index: 15; pointer-events: none; }
.joystick {
  position: absolute; left: calc(24px + var(--safe-left)); bottom: calc(30px + var(--safe-bottom));
  width: 126px; height: 126px; pointer-events: auto; touch-action: none;
}
.joystick-ring { position: absolute; inset: 0; border-radius: 50%; border: 1px solid rgba(230,185,78,.22); background: radial-gradient(circle, rgba(240,224,183,.03), rgba(9,8,6,.34)); box-shadow: inset 0 0 20px rgba(0,0,0,.25); }
.joystick-ring::before, .joystick-ring::after { content: ''; position: absolute; background: rgba(230,185,78,.13); }
.joystick-ring::before { width: 1px; left: 50%; top: 18px; bottom: 18px; }
.joystick-ring::after { height: 1px; top: 50%; left: 18px; right: 18px; }
.joystick-knob {
  position: absolute; left: 34px; top: 34px; width: 58px; height: 58px; border-radius: 50%;
  border: 1px solid rgba(230,185,78,.5);
  background: radial-gradient(circle at 40% 35%, rgba(240,224,183,.28), rgba(48,40,26,.7));
  box-shadow: 0 6px 18px rgba(0,0,0,.45), inset 0 0 12px rgba(230,185,78,.16);
  transition: transform .07s linear;
}
.touch-look-hint { position: absolute; right: calc(26px + var(--safe-right)); top: 50%; font: 500 8px/1 var(--sans); letter-spacing: .2em; color: rgba(242,232,207,.3); transform: translateY(-50%) rotate(90deg); pointer-events: none; }
.action-cluster {
  position: absolute; right: calc(18px + var(--safe-right)); bottom: calc(22px + var(--safe-bottom));
  width: 214px; height: 214px; pointer-events: none;
}
.touch-btn {
  position: absolute; pointer-events: auto; touch-action: none;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  border-radius: 50%; border: 1px solid rgba(230,185,78,.36);
  background: radial-gradient(circle at 42% 32%, rgba(242, 228, 190, .18), rgba(10, 9, 6, .7) 72%);
  box-shadow: 0 5px 16px rgba(0,0,0,.35), inset 0 0 15px rgba(230,185,78,.06);
  color: rgba(242,232,207,.82); transition: transform .08s ease, background .08s ease;
  backdrop-filter: blur(3px);
}
.touch-btn .glyph { font: 400 22px/1 var(--serif); color: #f5e1af; text-shadow: 0 0 10px rgba(230,185,78,.38); }
.touch-btn small { font: 500 6.5px/1 var(--sans); letter-spacing: .13em; color: rgba(242,232,207,.55); }
.touch-btn:active, .touch-btn.pressed { transform: scale(.9); background: radial-gradient(circle, rgba(230,185,78,.5), rgba(34,25,9,.8)); }
.touch-btn.jump { width: 82px; height: 82px; right: 4px; bottom: 8px; border-color: rgba(230,185,78,.56); }
.touch-btn.jump .glyph { font-size: 27px; }
.touch-btn.whip { width: 68px; height: 68px; right: 88px; bottom: 2px; }
.touch-btn.punch { width: 61px; height: 61px; right: 52px; bottom: 76px; }
.touch-btn.shoot { width: 54px; height: 54px; right: 0; bottom: 95px; }
.touch-btn.small { width: 47px; height: 47px; }
.touch-btn.small .glyph { font-size: 16px; }
.touch-btn.crouch { right: 155px; bottom: 15px; }
.touch-btn.interact { right: 114px; bottom: 119px; border-color: rgba(255,216,117,.55); opacity: .9; }
.touch-btn.interact.available { animation: interactPulse 1.1s ease infinite; }
@keyframes interactPulse { 50% { box-shadow: 0 0 0 6px rgba(230,185,78,.08), 0 0 22px rgba(230,185,78,.35); } }

/* ============================= SCREENS ============================= */
.screen { position: absolute; inset: 0; z-index: 20; }
.menu-screen { display: flex; flex-direction: column; overflow: hidden; background: radial-gradient(ellipse at 50% 42%, rgba(31,24,13,.08), rgba(5,4,3,.65) 65%, rgba(4,3,2,.95)); }
.menu-scrim {
  position: absolute; inset: 0; pointer-events: none;
  background:
    linear-gradient(90deg, rgba(5,4,3,.82) 0%, rgba(5,4,3,.35) 39%, transparent 56%, rgba(5,4,3,.18) 100%),
    linear-gradient(0deg, rgba(5,4,3,.92) 0%, transparent 30%, transparent 80%, rgba(5,4,3,.55) 100%);
}
.menu-topline { position: relative; z-index: 2; display: flex; align-items: center; gap: 16px; padding: calc(26px + var(--safe-top)) calc(34px + var(--safe-right)) 0 calc(34px + var(--safe-left)); }
.brand-mark {
  width: 37px; height: 37px; display: grid; place-items: center;
  border: 1px solid rgba(230,185,78,.62); border-radius: 50%;
  font: 700 16px/1 var(--serif); color: var(--gold-bright); letter-spacing: -.08em;
  box-shadow: inset 0 0 15px rgba(230,185,78,.12), 0 0 20px rgba(0,0,0,.35);
}
.edition { font: 500 9px/1 var(--sans); letter-spacing: .28em; color: rgba(242,232,207,.55); }
.menu-sound { margin-left: auto; }
.icon-button.sound-toggle { width: 36px; height: 36px; border: 1px solid rgba(230,185,78,.22); border-radius: 50%; display: grid; place-items: center; background: rgba(9,8,6,.28); }
.sound-toggle .sound-on, .sound-toggle .sound-off { font: 500 10px/1 var(--sans); letter-spacing: .06em; color: var(--sand); }
.sound-toggle.muted .sound-on { display: none; }
.sound-toggle:not(.muted) .sound-off { display: none; }
.menu-content { position: relative; z-index: 2; flex: 1; width: min(1340px, 92vw); margin: 0 auto; display: grid; grid-template-columns: 1.2fr .8fr; grid-template-rows: 1fr auto; align-items: center; gap: 3vw; }
.title-lockup { align-self: end; padding-bottom: 2vh; max-width: 720px; }
.kicker { display: flex; align-items: center; gap: 12px; margin-bottom: 17px; }
.kicker i { display: block; width: 44px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.kicker i:last-child { background: linear-gradient(90deg, var(--gold), transparent); }
.kicker span { font: 600 9px/1 var(--sans); letter-spacing: .34em; color: var(--sand); }
.title-lockup h1 { margin: 0; display: flex; flex-direction: column; font: 700 clamp(68px, 10.8vw, 168px)/0.76 var(--serif); letter-spacing: -.045em; text-transform: uppercase; color: #f1e4c2; text-shadow: 0 5px 0 rgba(42,25,8,.25), 0 18px 45px rgba(0,0,0,.58); }
.title-lockup h1 span:first-child { background: linear-gradient(180deg, #fff4d6 0%, #e8cd8b 42%, #a47a33 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 2px 0 rgba(63,39,10,.35)); }
.title-lockup h1 .title-jones { margin-left: clamp(35px, 10vw, 160px); font-size: .81em; letter-spacing: .01em; color: transparent; background: linear-gradient(180deg, #fcf0cf 0%, #c9a55d 54%, #75501f 100%); -webkit-background-clip: text; background-clip: text; filter: drop-shadow(0 2px 0 rgba(63,39,10,.4)); }
.subtitle { display: flex; align-items: baseline; gap: 13px; margin: 22px 0 15px clamp(38px, 10vw, 165px); }
.subtitle span { font: 500 9px/1 var(--sans); letter-spacing: .3em; color: rgba(242,232,207,.5); }
.subtitle strong { font: 600 clamp(14px, 1.35vw, 20px)/1 var(--serif); letter-spacing: .2em; color: var(--gold); }
.tagline { margin: 0 0 0 clamp(38px, 10vw, 165px); font: 400 clamp(13px, 1.05vw, 16px)/1.5 var(--serif); letter-spacing: .04em; color: rgba(242,232,207,.59); }
.menu-actions { align-self: end; justify-self: end; width: min(300px, 28vw); padding-bottom: 4vh; }
.menu-button {
  position: relative; width: 100%; padding: 14px 22px; margin-bottom: 9px;
  border: 1px solid rgba(230,185,78,.28); background: rgba(12, 10, 7, .34);
  font: 600 12px/1 var(--sans); letter-spacing: .23em; color: rgba(242,232,207,.78); text-align: center;
  transition: background .25s, border-color .25s, color .25s, transform .25s; overflow: hidden;
  backdrop-filter: blur(7px);
}
.menu-button:hover { border-color: rgba(230,185,78,.7); background: rgba(230,185,78,.1); color: #fff1c9; transform: translateX(-3px); }
.menu-button.primary {
  padding: 18px 22px; border-color: var(--gold); color: #1b1306;
  background: linear-gradient(105deg, #d8b25a, #f3d78c 45%, #c99a3f);
  font-size: 15px; letter-spacing: .28em; box-shadow: 0 8px 32px rgba(126, 82, 17, .24), inset 0 1px 0 rgba(255,250,218,.65);
}
.menu-button.primary:hover { background: linear-gradient(105deg, #efcd79, #ffe9aa 45%, #deb45b); color: #130d04; transform: translateX(-3px) translateY(-1px); box-shadow: 0 12px 38px rgba(171, 121, 34, .32), inset 0 1px 0 #fffbe4; }
.menu-button.primary.small { padding: 13px 18px; font-size: 12px; }
.menu-button.small { padding: 12px 16px; font-size: 10px; }
.menu-button.ghost { color: rgba(242,232,207,.42); border-color: rgba(242,232,207,.12); }
.menu-meta { display: flex; justify-content: space-between; margin-top: 14px; font: 500 8px/1 var(--sans); letter-spacing: .17em; color: rgba(242,232,207,.34); }
.menu-meta b { color: var(--sand); font-weight: 600; }
.feature-row { grid-column: 1 / -1; display: flex; gap: 0; margin: 0 0 calc(28px + var(--safe-bottom)); border-top: 1px solid rgba(230,185,78,.16); border-bottom: 1px solid rgba(230,185,78,.1); background: rgba(8,7,5,.24); backdrop-filter: blur(6px); }
.feature { flex: 1; display: grid; grid-template-columns: 30px 1fr; grid-template-rows: auto auto; align-content: center; gap: 2px 11px; padding: 13px 22px; border-right: 1px solid rgba(230,185,78,.1); }
.feature:last-child { border-right: 0; }
.feature-icon { grid-row: 1 / 3; align-self: center; font: 400 24px/1 var(--serif); color: var(--gold); opacity: .82; }
.feature b { font: 600 10px/1 var(--sans); letter-spacing: .16em; color: rgba(242,232,207,.72); }
.feature small { font: 400 9px/1 var(--sans); letter-spacing: .04em; color: rgba(242,232,207,.33); }
.menu-footer { position: relative; z-index: 2; display: flex; align-items: center; gap: 12px; padding: 0 calc(34px + var(--safe-right)) calc(22px + var(--safe-bottom)) calc(34px + var(--safe-left)); font: 500 8px/1 var(--sans); letter-spacing: .2em; color: rgba(242,232,207,.3); }
.footer-diamond { color: rgba(230,185,78,.44); font-size: 6px; }
.menu-footer .version { margin-left: auto; }
.corner { position: absolute; width: 28px; height: 28px; border-color: rgba(230,185,78,.4); border-style: solid; pointer-events: none; z-index: 3; }
.corner-tl { top: 18px; left: 18px; border-width: 1px 0 0 1px; }
.corner-tr { top: 18px; right: 18px; border-width: 1px 1px 0 0; }
.corner-bl { bottom: 18px; left: 18px; border-width: 0 0 1px 1px; }
.corner-br { bottom: 18px; right: 18px; border-width: 0 1px 1px 0; }

.panel-screen { display: flex; align-items: center; justify-content: center; padding: calc(25px + var(--safe-top)) calc(24px + var(--safe-right)) calc(25px + var(--safe-bottom)) calc(24px + var(--safe-left)); }
.panel-backdrop, .modal-backdrop { position: absolute; inset: 0; background: radial-gradient(ellipse at center, rgba(16,12,7,.84), rgba(5,4,3,.97)); backdrop-filter: blur(13px); }
.panel { position: relative; width: min(1120px, 92vw); max-height: 88vh; display: flex; flex-direction: column; padding: 26px 30px 30px; background: linear-gradient(155deg, rgba(29,24,16,.91), rgba(10,9,6,.97)); border: 1px solid rgba(230,185,78,.22); box-shadow: 0 30px 100px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,246,210,.06); }
.panel::before, .modal-card::before { content: ''; position: absolute; inset: 8px; border: 1px solid rgba(230,185,78,.08); pointer-events: none; }
.panel-header { display: flex; align-items: center; justify-content: space-between; gap: 25px; padding-bottom: 20px; border-bottom: 1px solid rgba(230,185,78,.18); }
.panel-header h2 { margin: 3px 0 0; font: 600 clamp(24px, 2.5vw, 36px)/1 var(--serif); letter-spacing: .04em; color: #f0e0b8; }
.text-button { font: 500 10px/1 var(--sans); letter-spacing: .18em; color: rgba(242,232,207,.5); padding: 8px 0; transition: color .2s; }
.text-button:hover { color: var(--gold-bright); }
.relic-total { text-align: right; display: flex; flex-direction: column; gap: 4px; }
.relic-total span { font: 500 8px/1 var(--sans); letter-spacing: .2em; color: rgba(242,232,207,.38); }
.relic-total b { font: 600 18px/1 var(--serif); color: var(--gold); }
.level-grid { overflow-y: auto; display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; padding: 18px 2px 4px; scrollbar-width: thin; scrollbar-color: rgba(230,185,78,.3) transparent; }
.biome-heading { grid-column: 1 / -1; display: flex; align-items: center; gap: 10px; margin-top: 4px; font: 600 8px/1 var(--sans); letter-spacing: .24em; color: var(--sand); }
.biome-heading::after { content: ''; flex: 1; height: 1px; background: linear-gradient(90deg, rgba(230,185,78,.26), transparent); }
.level-card { position: relative; min-height: 102px; padding: 11px; border: 1px solid rgba(230,185,78,.13); background: linear-gradient(145deg, rgba(255,241,197,.04), rgba(0,0,0,.2)); text-align: left; transition: border-color .2s, background .2s, transform .2s; overflow: hidden; }
.level-card:hover:not(.locked) { border-color: rgba(230,185,78,.52); background: linear-gradient(145deg, rgba(230,185,78,.11), rgba(0,0,0,.2)); transform: translateY(-2px); }
.level-card .num { font: 600 26px/1 var(--serif); color: rgba(230,185,78,.72); }
.level-card .name { display: block; margin-top: 9px; font: 600 10px/1.1 var(--sans); letter-spacing: .08em; color: rgba(242,232,207,.82); }
.level-card .meta { display: flex; align-items: center; justify-content: space-between; margin-top: 8px; font: 500 7px/1 var(--sans); letter-spacing: .12em; color: rgba(242,232,207,.3); }
.level-card .meta .idols { color: var(--gold); letter-spacing: .06em; }
.level-card .difficulty { display: flex; gap: 2px; }
.level-card .difficulty i { width: 4px; height: 4px; border-radius: 50%; background: rgba(230,185,78,.16); }
.level-card .difficulty i.on { background: var(--gold); }
.level-card.locked { cursor: not-allowed; opacity: .45; }
.level-card.locked::after { content: '⌑'; position: absolute; right: 10px; top: 8px; font-size: 15px; color: rgba(242,232,207,.33); }
.level-card.completed { border-color: rgba(230,185,78,.26); }
.level-card.completed::before { content: '✦'; position: absolute; right: 9px; top: 7px; color: var(--gold); font-size: 11px; text-shadow: 0 0 9px rgba(230,185,78,.55); }
.level-card.current { border-color: var(--gold); box-shadow: inset 0 0 25px rgba(230,185,78,.06); }
.level-card.current .num { color: var(--gold-bright); }
.level-card.boss { background: linear-gradient(145deg, rgba(156,62,34,.14), rgba(0,0,0,.3)); border-color: rgba(184,52,37,.3); }
.level-card.boss .num { color: #dc714b; }

.modal-screen { display: flex; align-items: center; justify-content: center; padding: 20px; }
.modal-card { position: relative; width: min(540px, 90vw); padding: 34px 38px 30px; text-align: center; background: linear-gradient(160deg, rgba(30,25,16,.96), rgba(10,9,6,.98)); border: 1px solid rgba(230,185,78,.24); box-shadow: 0 30px 120px rgba(0,0,0,.75), inset 0 1px 0 rgba(255,246,210,.06); }
.modal-card h2 { margin: 7px 0 7px; font: 600 clamp(27px, 4vw, 42px)/1.05 var(--serif); color: #f2e6c4; }
.modal-card p { margin: 0 0 22px; font: 400 12px/1.5 var(--sans); letter-spacing: .06em; color: rgba(242,232,207,.5); }
.modal-actions { display: flex; flex-direction: column; gap: 4px; width: min(280px, 100%); margin: 0 auto; }
.modal-actions.horizontal { flex-direction: row; justify-content: center; width: auto; flex-wrap: wrap; }
.modal-actions.horizontal .menu-button { width: auto; min-width: 132px; margin: 0; }
.relic-emblem { position: relative; width: 116px; height: 116px; margin: 6px auto 20px; display: flex; align-items: center; justify-content: center; gap: 11px; }
.relic-emblem::before, .relic-emblem::after { content: ''; position: absolute; inset: 0; border: 1px solid rgba(230,185,78,.25); transform: rotate(45deg); }
.relic-emblem::after { inset: 13px; border-color: rgba(230,185,78,.14); }
.relic-emblem span { width: 12px; height: 58px; background: linear-gradient(180deg, transparent, rgba(230,185,78,.65), transparent); transform: rotate(45deg); }
.relic-emblem i { width: 42px; height: 42px; border: 1px solid var(--gold); background: radial-gradient(circle, rgba(255,216,117,.7), rgba(186,125,31,.08) 66%); transform: rotate(45deg); box-shadow: 0 0 30px rgba(230,185,78,.26); }
.stats-row { display: flex; justify-content: center; gap: 0; margin: 0 0 24px; border-top: 1px solid rgba(230,185,78,.13); border-bottom: 1px solid rgba(230,185,78,.13); }
.stats-row div { flex: 1; padding: 12px 8px; border-right: 1px solid rgba(230,185,78,.1); }
.stats-row div:last-child { border-right: 0; }
.stats-row span { display: block; margin-bottom: 4px; font: 500 7px/1 var(--sans); letter-spacing: .2em; color: rgba(242,232,207,.35); }
.stats-row b { font: 600 18px/1 var(--serif); color: var(--gold-bright); }
.ending-card { width: min(600px, 92vw); }
.ending-card p { font-family: var(--serif); font-size: 13px; }
.ending-stats { display: flex; align-items: center; justify-content: space-between; width: 270px; margin: 19px auto 24px; padding: 14px 0; border-top: 1px solid rgba(230,185,78,.18); border-bottom: 1px solid rgba(230,185,78,.18); }
.ending-stats span { font: 500 8px/1 var(--sans); letter-spacing: .2em; color: rgba(242,232,207,.4); }
.ending-stats b { font: 600 24px/1 var(--serif); color: var(--gold-bright); }

.loading { position: absolute; inset: 0; z-index: 60; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 15px; background: #0b0906; transition: opacity .7s ease, visibility .7s; }
.loading.done { opacity: 0; visibility: hidden; }
.loading-mark { width: 58px; height: 58px; display: grid; place-items: center; border: 1px solid rgba(230,185,78,.48); border-radius: 50%; font: 700 23px/1 var(--serif); color: var(--gold); letter-spacing: -.08em; box-shadow: 0 0 35px rgba(230,185,78,.1); animation: loadPulse 2s ease infinite; }
.loading-track { width: 170px; height: 1px; background: rgba(230,185,78,.12); overflow: hidden; }
.loading-track i { display: block; width: 0; height: 100%; background: linear-gradient(90deg, rgba(230,185,78,.2), var(--gold), rgba(230,185,78,.2)); transition: width .35s; }
.loading span { font: 500 8px/1 var(--sans); letter-spacing: .24em; color: rgba(242,232,207,.35); }
@keyframes loadPulse { 50% { box-shadow: 0 0 45px rgba(230,185,78,.24); border-color: rgba(230,185,78,.8); } }

.rotate-prompt { position: absolute; z-index: 70; inset: 0; background: rgba(8,7,5,.94); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; text-align: center; padding: 30px; }
.rotate-prompt span { font: 400 52px/1 var(--serif); color: var(--gold); animation: rotateHint 2s ease infinite; }
.rotate-prompt p { font: 500 12px/1.4 var(--sans); letter-spacing: .12em; color: var(--bone); max-width: 220px; }
@keyframes rotateHint { 50% { transform: rotate(90deg); } }

/* reveal animations */
.menu-screen:not(.hidden) .title-lockup { animation: revealUp .9s cubic-bezier(.2,.7,.2,1) both; }
.menu-screen:not(.hidden) .menu-actions { animation: revealUp .9s .14s cubic-bezier(.2,.7,.2,1) both; }
.menu-screen:not(.hidden) .feature-row { animation: revealUp .9s .26s cubic-bezier(.2,.7,.2,1) both; }
.menu-screen:not(.hidden) .menu-topline, .menu-screen:not(.hidden) .menu-footer { animation: fadeIn 1.2s .35s ease both; }
@keyframes revealUp { from { opacity: 0; transform: translateY(20px); } }
@keyframes fadeIn { from { opacity: 0; } }

@media (max-width: 980px) {
  .menu-content { grid-template-columns: 1fr .72fr; width: 90vw; }
  .feature-row { display: none; }
  .menu-actions { padding-bottom: 8vh; width: min(260px, 32vw); }
  .level-grid { grid-template-columns: repeat(4, 1fr); }
  .desktop-hints { gap: 9px; }
  .desktop-hints span:nth-child(n+6) { display: none; }
}
@media (max-width: 700px) {
  .hud { padding: calc(10px + var(--safe-top)) calc(10px + var(--safe-right)) calc(10px + var(--safe-bottom)) calc(10px + var(--safe-left)); }
  .hud-top { gap: 7px; }
  .level-plate { min-width: 73px; padding: 7px 8px 6px; }
  .level-plate strong { font-size: 20px; margin-right: 4px; }
  .level-plate > span:last-child { font-size: 8px; display: block; margin-top: 2px; }
  .hearts-block { position: absolute; left: 50%; transform: translateX(-50%); top: calc(10px + var(--safe-top)); padding: 0; gap: 0; }
  .heart { width: 21px; height: 20px; }
  .score { display: none; }
  .objective-card { position: absolute; top: calc(38px + var(--safe-top)); left: 50%; transform: translateX(-50%); width: 44vw; padding: 4px 8px; }
  #hud-objective { font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
